package local.paladinclient;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import java.util.stream.Stream;
import net.minecraft.client.*;import net.minecraft.client.gui.screens.inventory.InventoryScreen;import net.minecraft.network.chat.Component;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.effect.*;import net.minecraft.world.item.*;import net.minecraft.server.level.ServerPlayer;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;
