@Mod(value="paladin_client_probe",dist=Dist.CLIENT) public class PaladinClientProbe {
 final List<String> results=Collections.synchronizedList(new ArrayList<>());final AtomicReference<String> pending=new AtomicReference<>();int ticks,phase,at;boolean hidden,done,clientStarted;long channelStart;UUID catID;
 interface Work{void run(ServerPlayer p)throws Exception;}void check(boolean b,String s){results.add((b?"PASS ":"FAIL ")+s);}void near(double a,double b,String s){check(Math.abs(a-b)<.02,s+" actual="+a+" expected="+b);}
 Category category(){return SkillsAPI.getCategory(Identifier.parse("skill_tree_rpgs:class_skills")).orElseThrow();}
 void server(Work work){var mc=Minecraft.getInstance();pending.set("waiting");mc.getSingleplayerServer().execute(()->{try{work.run(mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()));pending.set("ready");}catch(Throwable e){e.printStackTrace();check(false,"server exception "+e);pending.set("failed");}});}
 void next(){phase++;at=ticks;}void shot(String s){Screenshot.grab(Minecraft.getInstance(),false);results.add("SCREENSHOT "+s);}
 List<String> description(String id)throws Exception{var effect=Minecraft.getInstance().player.getEffect(PaladinRevamp.effect(id));check(effect!=null,"client effect "+id);var type=Class.forName("fuzs.effectinsights.common.client.gui.tooltip.MobEffectTooltipLines");var extractor=type.getField("DESCRIPTION").get(null);var method=extractor.getClass().getMethod("getTooltipLines",Object.class,int.class);method.setAccessible(true);return ((Stream<Component>)method.invoke(extractor,effect,240)).map(Component::getString).toList();}
 void sword(ServerPlayer p,String spell){var item=new ItemStack(Items.IRON_SWORD);item.set(net.spell_engine.api.spell.SpellDataComponents.SPELL_CONTAINER,net.spell_engine.api.spell.container.SpellContainers.forWeapon(net.spell_engine.api.spell.container.SpellContainer.ContentType.ANY,List.of(Identifier.parse(spell))));p.getInventory().setSelectedSlot(0);p.getInventory().setItem(0,item);p.getInventory().setItem(1,new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(Identifier.parse("runes:healing_stone")),64));p.inventoryMenu.broadcastFullState();((SpellContainerSource.Owner)p).spellContainerCache().clear();SpellContainerSource.update(p);}
 void inventory()throws Exception{var mc=Minecraft.getInstance();if(mc.gui.hud.isHidden())mc.gui.hud.toggle();mc.setScreenAndShow(new InventoryScreen(mc.player));double x=mc.getWindow().getGuiScaledWidth()/2d+100,y=(mc.getWindow().getGuiScaledHeight()-166)/2d+12;for(String f:List.of("xpos","ypos")){var field=mc.mouseHandler.getClass().getDeclaredField(f);field.setAccessible(true);field.setDouble(mc.mouseHandler,(f.equals("xpos")?x:y)*mc.getWindow().getGuiScale());}}
 public PaladinClientProbe(){NeoForge.EVENT_BUS.addListener(this::tick);}
 void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(!hidden){org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().handle());mc.options.pauseOnLostFocus=false;hidden=true;}if(done||mc.player==null||mc.level==null)return;mc.mouseHandler.releaseMouse();ticks++;
 try{if(ticks>2600)throw new AssertionError("timeout phase="+phase);if(phase==0&&ticks>=30){server(p->{p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.level().getGameRules().set(net.minecraft.world.level.gamerules.GameRules.NATURAL_HEALTH_REGENERATION,false,p.level().getServer());for(var old:p.level().getEntitiesOfClass(net.minecraft.world.entity.Mob.class,p.getBoundingBox().inflate(200)))old.discard();p.getInventory().clearContent();for(var slot:EquipmentSlot.VALUES)if(slot.isArmor())p.setItemSlot(slot,ItemStack.EMPTY);PaladinUltimates.cleanup(p);p.removeAllEffects();PaladinRevamp.clear(p);var c=category();c.unlock(p);c.resetSkills(p);c.setExtraPoints(p,1000);for(String n:List.of("tdimeso8ajcwiygp","c1jm4e1hmf87kgvp","864ddcqh44qedq2j"))c.getSkill(n).orElseThrow().unlock(p);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);p.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(40);p.getAttribute(SpellSchools.HEALING.attributeEntry).setBaseValue(20);p.getAttribute(Attributes.ARMOR).setBaseValue(20);p.getAttribute(SpellPowerMechanics.CRITICAL_CHANCE.attributeEntry).setBaseValue(0);for(String spell:List.of(PaladinUltimates.BANNER,PaladinUltimates.PURGATORY))((SpellCaster.Player)p).getCooldownManager().setDurationLeft(PaladinRevamp.spell(p,spell),0);p.level().getServer().getCommands().performPrefixedCommand(p.createCommandSourceStack(),"time set day");p.getFoodData().setFoodLevel(20);for(int x=-14;x<=14;x++)for(int z=-14;z<=14;z++)p.level().setBlockAndUpdate(new net.minecraft.core.BlockPos(x,100,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());p.teleportTo(.5,101,.5);p.setYRot(0);p.setXRot(0);sword(p,PaladinUltimates.BANNER);var cat=EntityTypes.CAT.create(p.level(),EntitySpawnReason.COMMAND);cat.setPos(2,101,3);((net.minecraft.world.entity.Mob)cat).setNoAi(true);cat.setOwnerReference(EntityReference.of(p.getUUID()));p.level().addFreshEntity(cat);catID=cat.getUUID();});next();return;}
  if(phase==0||ticks-at<20||"waiting".equals(pending.get()))return;if("failed".equals(pending.get())){finish();return;}
  switch(phase){
   case 1->{check(net.neoforged.fml.ModList.get().isLoaded("enhancedcats"),"Enhanced Cats loaded on actual client");check(!net.neoforged.fml.ModList.get().isLoaded("kingdomcats"),"Cute Cats absent from isolatedclient");mc.player.getInventory().setSelectedSlot(0);mc.getConnection().send(new net.minecraft.network.protocol.game.ServerboundSetCarriedItemPacket(0));server(p->{check(SpellCast.Option.allOf(p).stream().anyMatch(o->o.id().toString().equals(PaladinUltimates.BANNER)),"native Banner castoption");((SpellCaster.Player)p).getInteractor().requestCast(Identifier.parse(PaladinUltimates.BANNER),SpellCast.TargetSnapshot.EMPTY);});next();}
   case 2->{check(mc.player.hasEffect(PaladinRevamp.effect(PaladinUltimates.BANNER)),"native Banner cast applies followingaura");check(String.join(" ",description(PaladinUltimates.BANNER)).contains("Attack speed"),"Banner resolved receiveddetails");server(p->{var b=PaladinUltimates.bannerOf(p);check(b!=null&&b.radius==8,"native Improved Bannerradius8");p.teleportTo(3.5,101,2.5);});if(!mc.gui.hud.isHidden())mc.gui.hud.toggle();mc.options.setCameraType(CameraType.THIRD_PERSON_FRONT);next();}
   case 3->{shot("moving shoulder Banner and party pulse");for(var entity:mc.level.entitiesForRendering())if(entity instanceof net.spell_engine.entity.SpellCloud cloud&&entity.getType().toString().contains("battle_banner")){check(entity.position().distanceTo(mc.player.position())<1.5,"client Banner follows movedcaster");check(entity.getBoundingBox().getSize()>.1,"client Banner has visible renderbounds");results.add("CLIENT BANNER "+entity.position()+" scale="+cloud.getRenderScale(1)+" spell="+cloud.getSpellEntry()+" active="+cloud.isActive());}server(p->{var b=PaladinUltimates.bannerOf(p);check(!b.model.isRemoved(),"Banner model remains alive after firstsecond");check(b.model.position().distanceTo(p.position())<1.5,"Banner model follows movedplayer");});inventory();next();}
   case 4->{shot("Banner received buff percentages");mc.setScreenAndShow(null);mc.options.setCameraType(CameraType.FIRST_PERSON);server(p->{PaladinUltimates.cleanup(p);p.removeAllEffects();var c=category();c.resetSkills(p);c.getSkill("tdimeso8ajcwiygp").orElseThrow().unlock(p);c.getSkill("nq5m15dhmva3d2lw").orElseThrow().unlock(p);p.getAttribute(SpellSchools.HEALING.attributeEntry).setBaseValue(30);sword(p,PaladinUltimates.PURGATORY);p.setHealth(1000);});next();}
   case 5->{if(!clientStarted){mc.player.getInventory().setSelectedSlot(0);mc.getConnection().send(new net.minecraft.network.protocol.game.ServerboundSetCarriedItemPacket(0));var attempt=((SpellCaster.Client)mc.player).getCastController().startSpellCast(mc.player.getMainHandItem(),PaladinRevamp.spell(mc.player,PaladinUltimates.PURGATORY));results.add("CLIENT CAST "+attempt);clientStarted=true;channelStart=mc.level.getGameTime();at=ticks;return;}check(mc.player.hasEffect(PaladinRevamp.effect(PaladinUltimates.STANCE)),"native Purgatory cast startschannel");server(p->{check(PaladinUltimates.channelOf(p)!=null,"native cast lifecycle registerschannel");near(p.getHealth(),1000,"firststage noHPcost");check(!PaladinRevamp.rollAllowed(p),"channel serverrejectsroll");});if(!mc.gui.hud.isHidden())mc.gui.hud.toggle();mc.options.setCameraType(CameraType.THIRD_PERSON_FRONT);next();}
   case 6->{if(ticks-at==20)shot("Purgatory firststage stance orangeglint");if(mc.level.getGameTime()-channelStart<215)return;server(p->{var c=PaladinUltimates.channelOf(p);check(c!=null&&c.pulses>=20&&c.pulses<40,"native10s enters middlestage");check(p.getHealth()<1000,"native middlephase startsHPcost");});next();}
   case 7->{if(ticks-at==20)shot("Purgatory middlestage fire sparks and ring");if(mc.level.getGameTime()-channelStart<420)return;server(p->{var c=PaladinUltimates.channelOf(p);check(c!=null&&c.pulses>=40,"native20s entersfinalphase");check(c!=null&&PaladinUltimates.protectionTicks(c.p)>=4,"finalphase pulseprotection configured");results.add("FINAL PHASE "+(c==null?"ended":"pulses="+c.pulses+" P="+c.p+" protection="+p.hasEffect(PaladinRevamp.effect(PaladinUltimates.IMMUNITY))));});next();}
   case 8->{if(ticks-at==20)shot("Purgatory finalstage redfire");if(ticks-at==20)check(String.join(" ",description(PaladinUltimates.STANCE)).contains("HP cost per pulse: 3"),"received finalphase selfcostdetails");if(mc.level.getGameTime()-channelStart<625)return;server(p->{check(PaladinUltimates.channelOf(p)==null,"native30s channelends");check(!p.hasEffect(PaladinRevamp.effect(PaladinUltimates.STANCE)),"native endclearsstanceglint");near(p.getHealth(),897,"native fullchannel pays103HP");});next();}
   case 9->{shot("Purgatory completion and restoredpose");mc.options.setCameraType(CameraType.FIRST_PERSON);server(p->{p.removeAllEffects();PaladinUltimates.cleanup(p);var c=category();c.resetSkills(p);c.getSkill("tdimeso8ajcwiygp").orElseThrow().unlock(p);c.getSkill("zc9xk0tkjuk0kd39").orElseThrow().unlock(p);p.setHealth(350);});next();}
   case 10->{check(String.join(" ",description(PaladinUltimates.REINFORCED)).contains("20%"),"Reinforced realallocation lowHP20%");inventory();next();}
   case 11->{shot("Reinforced actual20% bonuses");mc.setScreenAndShow(null);mc.options.setCameraType(CameraType.THIRD_PERSON_FRONT);server(p->{p.removeAllEffects();PaladinUltimates.cleanup(p);p.setHealth(1000);p.teleportTo(.5,101,.5);p.setYRot(-35);});next();}
   case 12->{var cats=new ArrayList<Entity>();for(var entity:mc.level.entitiesForRendering())if(entity.getUUID().equals(catID))cats.add(entity);check(cats.size()==1,"Enhanced Cats cat spawnedandsynchronized");if(!cats.isEmpty()){var renderer=mc.getEntityRenderDispatcher().getRenderer(cats.getFirst());check(renderer.getClass().getName().contains("enhancedcats"),"Enhanced Cats renderer active "+renderer.getClass().getName());}shot("Enhanced Cats replacement rendering");for(String passive:List.of(PaladinUltimates.ARDENT_SKILL,PaladinUltimates.REINFORCED_SKILL)){var lines=net.spell_engine.client.gui.SpellTooltip.spellDescriptionWithDetails(Identifier.parse(passive),mc.player,ItemStack.EMPTY,0).stream().map(Component::getString).toList();results.add("PASSIVE PANEL "+passive+" "+lines);check(lines.stream().anyMatch(l->l.startsWith(passive.equals(PaladinUltimates.ARDENT_SKILL)?"Triggered by":"Active below")),"native customtriggerrow "+passive);check(lines.stream().noneMatch(l->l.contains("{impact}")||l.contains("%%")||l.contains("floor")),"clean displayedpercentagecopy "+passive);}check(net.minecraft.client.resources.language.I18n.get("spell.paladins.immolation.name").equals("Purgatory"),"Purgatory localizedname");check(net.minecraft.client.resources.language.I18n.get("spell.skill_tree_rpgs.paladin_tier_4_spell_2_modifier_2.name").equals("Final Resolute"),"Final Resolute localizednode");finish();}
  }
 }catch(Throwable e){e.printStackTrace();check(false,"client exception "+e);finish();}}
 void finish(){done=true;var mc=Minecraft.getInstance();try{Files.write(mc.gameDirectory.toPath().resolve("client-checks.txt"),results);Files.writeString(mc.gameDirectory.toPath().resolve("client-result.txt"),(results.stream().anyMatch(s->s.startsWith("FAIL"))?"FAIL":"PASS")+" "+results.stream().filter(s->s.startsWith("PASS")).count()+" checks\n");}catch(Exception e){throw new RuntimeException(e);}mc.stop();}
}
